// --- Update-dismissed persistence -------------------------------------------
// Stored at ~/Library/Application Support/EchoJay/update_dismissed.json
// Format: { "version": "1.2.0", "dismissedAtSeconds": 1714678800 }
//   - version: which latestVersion the user dismissed
//   - dismissedAtSeconds: Unix epoch when they clicked Not Now
// We re-prompt 3 days after the last dismissal, OR immediately if a newer
// version appears.

// Returns true if `a` is strictly newer than `b`, using dot-separated numeric
// comparison. Handles 1.10.0 > 1.2.0 correctly (numeric, not lexicographic).
// Trailing components in either string are treated as 0 (so "1.2" == "1.2.0").
// Non-numeric tokens are treated as 0.
static bool isVersionNewer(const juce::String& a, const juce::String& b)
{
    auto partsA = juce::StringArray::fromTokens(a, ".", "");
    auto partsB = juce::StringArray::fromTokens(b, ".", "");
    int n = juce::jmax(partsA.size(), partsB.size());
    for (int i = 0; i < n; ++i)
    {
        int ai = (i < partsA.size()) ? partsA[i].getIntValue() : 0;
        int bi = (i < partsB.size()) ? partsB[i].getIntValue() : 0;
        if (ai > bi) return true;
        if (ai < bi) return false;
    }
    return false;  // equal — not newer
}

// ===========================================================================
//  Saved-chain list cache (Session B, Chain sidebar)
// ===========================================================================
// Without this, the Chain sidebar offline is: up to a 10s wait, then an
// error, then nothing. The feature does not degrade, it disappears. So the
// last successful list is kept on disk and rendered immediately, and a failed
// refresh leaves it on screen rather than replacing it with an error.
//
// Keyed by a hash of the account email, so switching accounts cannot show you
// someone else's chains, and the file never contains the address itself.
//
// What is NOT cached: `state`. The list has never carried it (that is the
// point of hasState), so opening a chain still needs the network. A cached
// row must never imply otherwise.
static juce::File chainListCacheFile()
{
    auto appData = juce::File::getSpecialLocation(juce::File::userApplicationDataDirectory);
   #if JUCE_MAC
    return appData.getChildFile("Application Support/EchoJay/chain_list_cache.json");
   #else
    return appData.getChildFile("EchoJay/chain_list_cache.json");
   #endif
}

static juce::String chainCacheAccountKey(const juce::String& email)
{
    if (email.isEmpty()) return {};
    return juce::SHA256(email.trim().toLowerCase().toUTF8()).toHexString().substring(0, 16);
}

static void writeChainListCache(const juce::String& email, const juce::var& chains)
{
    const auto key = chainCacheAccountKey(email);
    if (key.isEmpty() || !chains.isArray()) return;
    auto root = std::make_unique<juce::DynamicObject>();
    root->setProperty("account", key);
    // Stored as EPOCH MILLIS, not a formatted string: the label is rendered
    // in the user's current locale and timezone at paint time, so a machine
    // that travels does not show a stale clock.
    root->setProperty("fetchedAtMs", (juce::int64) juce::Time::currentTimeMillis());
    root->setProperty("chains", chains);
    auto f = chainListCacheFile();
    f.getParentDirectory().createDirectory();
    f.replaceWithText(juce::JSON::toString(juce::var(root.release()), true));
}

// Returns the cached rows, or a void var when there is nothing usable for
// THIS account. fetchedAtMsOut is 0 when nothing was read.
static juce::var readChainListCache(const juce::String& email, juce::int64& fetchedAtMsOut)
{
    fetchedAtMsOut = 0;
    const auto key = chainCacheAccountKey(email);
    if (key.isEmpty()) return {};
    auto f = chainListCacheFile();
    if (!f.existsAsFile()) return {};
    auto parsed = juce::JSON::parse(f.loadFileAsString());
    auto* obj = parsed.getDynamicObject();
    if (obj == nullptr) return {};
    // A cache written by a different account is not ours to show.
    if (obj->getProperty("account").toString() != key) return {};
    fetchedAtMsOut = (juce::int64) obj->getProperty("fetchedAtMs");
    auto chains = obj->getProperty("chains");
    return chains.isArray() ? chains : juce::var();
}

// ===========================================================================
//  Dashboard payload cache (Session C)
// ===========================================================================
// THE SAME PATTERN as the chain list above, deliberately, rather than a second
// one: last successful payload on disk, rendered immediately on opening the
// tab, refreshed behind it, and a failed refresh leaves it on screen with its
// timestamp instead of replacing it with an error.
//
// Keyed by a hash of the account email for the same reason: switching accounts
// must not show you someone else's projects, and the file never contains the
// address itself.
static juce::File dashboardCacheFile()
{
    auto appData = juce::File::getSpecialLocation(juce::File::userApplicationDataDirectory);
   #if JUCE_MAC
    return appData.getChildFile("Application Support/EchoJay/dashboard_cache.json");
   #else
    return appData.getChildFile("EchoJay/dashboard_cache.json");
   #endif
}

static void writeDashboardCache(const juce::String& email, const juce::var& payload)
{
    const auto key = chainCacheAccountKey(email);
    if (key.isEmpty() || payload.getDynamicObject() == nullptr) return;
    auto root = std::make_unique<juce::DynamicObject>();
    root->setProperty("account", key);
    // Epoch millis, not a formatted string: the label renders in the user's
    // current locale and timezone at paint time, so a laptop that travels does
    // not show a stale clock.
    root->setProperty("fetchedAtMs", (juce::int64) juce::Time::currentTimeMillis());
    root->setProperty("payload", payload);
    auto f = dashboardCacheFile();
    f.getParentDirectory().createDirectory();
    f.replaceWithText(juce::JSON::toString(juce::var(root.release()), true));
}

// Returns the cached payload, or a void var when there is nothing usable for
// THIS account. fetchedAtMsOut is 0 when nothing was read.
static juce::var readDashboardCache(const juce::String& email, juce::int64& fetchedAtMsOut)
{
    fetchedAtMsOut = 0;
    const auto key = chainCacheAccountKey(email);
    if (key.isEmpty()) return {};
    auto f = dashboardCacheFile();
    if (!f.existsAsFile()) return {};
    auto parsed = juce::JSON::parse(f.loadFileAsString());
    auto* obj = parsed.getDynamicObject();
    if (obj == nullptr) return {};
    if (obj->getProperty("account").toString() != key) return {};
    fetchedAtMsOut = (juce::int64) obj->getProperty("fetchedAtMs");
    return obj->getProperty("payload");
}

static juce::File updateDismissFile()
{
    auto appData = juce::File::getSpecialLocation(juce::File::userApplicationDataDirectory);
   #if JUCE_MAC
    return appData.getChildFile("Application Support/EchoJay/update_dismissed.json");
   #else
    return appData.getChildFile("EchoJay/update_dismissed.json");
   #endif
}

// Returns true if we should suppress the overlay because the user dismissed
// THIS version less than 3 days ago.
static bool isUpdateDismissalActive(const juce::String& versionToCheck)
{
    auto f = updateDismissFile();
    if (!f.existsAsFile()) return false;
    auto json = juce::JSON::parse(f);
    auto* obj = json.getDynamicObject();
    if (obj == nullptr) return false;
    auto storedVersion = obj->getProperty("version").toString();
    auto dismissedAt = (juce::int64)(double)obj->getProperty("dismissedAtSeconds");
    if (storedVersion != versionToCheck) return false;  // different version → re-prompt
    auto nowSec = juce::Time::currentTimeMillis() / 1000;
    auto threeDaysSec = (juce::int64)(3 * 24 * 60 * 60);
    return (nowSec - dismissedAt) < threeDaysSec;
}

static void recordUpdateDismissal(const juce::String& versionDismissed)
{
    auto f = updateDismissFile();
    f.getParentDirectory().createDirectory();
    juce::DynamicObject::Ptr obj = new juce::DynamicObject();
    obj->setProperty("version", versionDismissed);
    obj->setProperty("dismissedAtSeconds", (double)(juce::Time::currentTimeMillis() / 1000));
    f.replaceWithText(juce::JSON::toString(juce::var(obj.get())));
}

